-- =====================================================================
-- seed.sql  -  deterministic, FICTIONAL sample data (all seven tables)
-- Run AFTER schema.sql, as appliance_app:  @database/seed.sql
--
-- SAFE TO RE-RUN: every statement is a MERGE keyed on a natural unique key
-- (category name, supplier name, model number, e-mail, invoice number,
-- sale+product), so a second run inserts nothing new and never overwrites
-- or deletes rows the user has since changed. Generated ids come from the
-- identity columns, so foreign keys are resolved by joining on those keys.
-- Parents are loaded before children. STOCK_QTY values are the CURRENT
-- stock after the seeded sales (no stock arithmetic is performed here).
-- Sale totals/line totals were computed from the listed prices.
-- All names, e-mails (example.com) and phone numbers are invented.
-- =====================================================================
SET DEFINE OFF
WHENEVER SQLERROR EXIT FAILURE ROLLBACK

-- Safety guard: refuse to create application objects as SYS/SYSTEM or in CDB$ROOT.
BEGIN
  IF SYS_CONTEXT('USERENV', 'CURRENT_USER') IN ('SYS', 'SYSTEM')
     OR SYS_CONTEXT('USERENV', 'CON_NAME') = 'CDB$ROOT' THEN
    RAISE_APPLICATION_ERROR(-20999,
      'Run this script as the application user in XEPDB1 (sqlplus appliance_app@localhost:1521/XEPDB1), not SYS/SYSTEM or CDB$ROOT.');
  END IF;
END;
/

-- 1. CATEGORIES
MERGE INTO CATEGORIES t USING (
    SELECT 'Refrigerators' AS CATEGORY_NAME, 'Single and double door refrigerators' AS DESCRIPTION FROM DUAL
    UNION ALL SELECT 'Washing Machines' AS CATEGORY_NAME, 'Front and top load washers' AS DESCRIPTION FROM DUAL
    UNION ALL SELECT 'Air Conditioners' AS CATEGORY_NAME, 'Split and window air conditioners' AS DESCRIPTION FROM DUAL
    UNION ALL SELECT 'Televisions' AS CATEGORY_NAME, 'LED and smart televisions' AS DESCRIPTION FROM DUAL
    UNION ALL SELECT 'Microwave Ovens' AS CATEGORY_NAME, 'Solo and convection microwave ovens' AS DESCRIPTION FROM DUAL
    UNION ALL SELECT 'Small Kitchen Appliances' AS CATEGORY_NAME, 'Mixers, kettles and cooktops' AS DESCRIPTION FROM DUAL
) s ON (t.CATEGORY_NAME = s.CATEGORY_NAME)
WHEN NOT MATCHED THEN INSERT (CATEGORY_NAME, DESCRIPTION) VALUES (s.CATEGORY_NAME, s.DESCRIPTION);

-- 2. SUPPLIERS
MERGE INTO SUPPLIERS t USING (
    SELECT 'Northwind Appliances Distribution' AS SUPPLIER_NAME, 'Priya Raman' AS CONTACT_PERSON, 'sales@northwind-demo.example.com' AS EMAIL, '9000000101' AS PHONE, '12 Market Road, Demo City' AS ADDRESS FROM DUAL
    UNION ALL SELECT 'BrightHome Wholesale' AS SUPPLIER_NAME, 'Arun Dsouza' AS CONTACT_PERSON, 'orders@brighthome-demo.example.com' AS EMAIL, '9000000102' AS PHONE, '44 Industrial Estate, Demo City' AS ADDRESS FROM DUAL
    UNION ALL SELECT 'Orion Electronics Supply' AS SUPPLIER_NAME, 'Neha Kulkarni' AS CONTACT_PERSON, 'support@orion-demo.example.com' AS EMAIL, '9000000103' AS PHONE, '7 Tech Park, Demo City' AS ADDRESS FROM DUAL
    UNION ALL SELECT 'Zenith Domestic Traders' AS SUPPLIER_NAME, 'Vikram Shenoy' AS CONTACT_PERSON, 'contact@zenith-demo.example.com' AS EMAIL, '9000000104' AS PHONE, '90 Harbour Lane, Demo City' AS ADDRESS FROM DUAL
) s ON (t.SUPPLIER_NAME = s.SUPPLIER_NAME)
WHEN NOT MATCHED THEN INSERT (SUPPLIER_NAME, CONTACT_PERSON, EMAIL, PHONE, ADDRESS)
 VALUES (s.SUPPLIER_NAME, s.CONTACT_PERSON, s.EMAIL, s.PHONE, s.ADDRESS);

-- 3. CUSTOMERS
MERGE INTO CUSTOMERS t USING (
    SELECT 'Anita Rao' AS FULL_NAME, 'anita.rao@demo-mail.example.com' AS EMAIL, '9000001001' AS PHONE, '21 Lake View, Demo City' AS ADDRESS FROM DUAL
    UNION ALL SELECT 'Bharat Kamath' AS FULL_NAME, 'bharat.kamath@demo-mail.example.com' AS EMAIL, '9000001002' AS PHONE, '8 Temple Street, Demo City' AS ADDRESS FROM DUAL
    UNION ALL SELECT 'Chitra Iyer' AS FULL_NAME, 'chitra.iyer@demo-mail.example.com' AS EMAIL, '9000001003' AS PHONE, '55 Garden Colony, Demo City' AS ADDRESS FROM DUAL
    UNION ALL SELECT 'Dev Naik' AS FULL_NAME, 'dev.naik@demo-mail.example.com' AS EMAIL, '9000001004' AS PHONE, '3 Sea Face Road, Demo City' AS ADDRESS FROM DUAL
    UNION ALL SELECT 'Esha Pinto' AS FULL_NAME, 'esha.pinto@demo-mail.example.com' AS EMAIL, '9000001005' AS PHONE, '19 Hill Park, Demo City' AS ADDRESS FROM DUAL
    UNION ALL SELECT 'Farhan Sheikh' AS FULL_NAME, 'farhan.sheikh@demo-mail.example.com' AS EMAIL, '9000001006' AS PHONE, '67 Station Road, Demo City' AS ADDRESS FROM DUAL
    UNION ALL SELECT 'Gita Bhat' AS FULL_NAME, 'gita.bhat@demo-mail.example.com' AS EMAIL, '9000001007' AS PHONE, '14 Mill Lane, Demo City' AS ADDRESS FROM DUAL
    UNION ALL SELECT 'Harish Kini' AS FULL_NAME, 'harish.kini@demo-mail.example.com' AS EMAIL, '9000001008' AS PHONE, '2 River Bend, Demo City' AS ADDRESS FROM DUAL
) s ON (t.EMAIL = s.EMAIL)
WHEN NOT MATCHED THEN INSERT (FULL_NAME, EMAIL, PHONE, ADDRESS)
 VALUES (s.FULL_NAME, s.EMAIL, s.PHONE, s.ADDRESS);

-- 4. EMPLOYEES
MERGE INTO EMPLOYEES t USING (
    SELECT 'Asha Menon' AS FULL_NAME, 'asha.menon@applstore-demo.example.com' AS EMAIL, '9000002001' AS PHONE, 'Sales Associate' AS JOB_TITLE, DATE '2022-06-01' AS HIRE_DATE FROM DUAL
    UNION ALL SELECT 'Rohan Pereira' AS FULL_NAME, 'rohan.pereira@applstore-demo.example.com' AS EMAIL, '9000002002' AS PHONE, 'Sales Associate' AS JOB_TITLE, DATE '2023-01-16' AS HIRE_DATE FROM DUAL
    UNION ALL SELECT 'Meera Nair' AS FULL_NAME, 'meera.nair@applstore-demo.example.com' AS EMAIL, '9000002003' AS PHONE, 'Store Manager' AS JOB_TITLE, DATE '2020-03-09' AS HIRE_DATE FROM DUAL
    UNION ALL SELECT 'Karan Shetty' AS FULL_NAME, 'karan.shetty@applstore-demo.example.com' AS EMAIL, '9000002004' AS PHONE, 'Cashier' AS JOB_TITLE, DATE '2024-08-05' AS HIRE_DATE FROM DUAL
) s ON (t.EMAIL = s.EMAIL)
WHEN NOT MATCHED THEN INSERT (FULL_NAME, EMAIL, PHONE, JOB_TITLE, HIRE_DATE)
 VALUES (s.FULL_NAME, s.EMAIL, s.PHONE, s.JOB_TITLE, s.HIRE_DATE);

-- 5. PRODUCTS (category / supplier resolved by name)
MERGE INTO PRODUCTS t USING (
  SELECT x.PRODUCT_NAME, x.BRAND, x.MODEL_NO, c.CATEGORY_ID, sp.SUPPLIER_ID,
         x.UNIT_PRICE, x.STOCK_QTY, x.REORDER_LEVEL, x.WARRANTY_MONTHS
  FROM (
    SELECT 'Arctiva 260L Double Door Refrigerator' AS PRODUCT_NAME, 'Arctiva' AS BRAND, 'ARC-RF260' AS MODEL_NO, 'Refrigerators' AS CAT_NAME, 'Northwind Appliances Distribution' AS SUP_NAME, 28999.00 AS UNIT_PRICE, 12 AS STOCK_QTY, 5 AS REORDER_LEVEL, 24 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'Arctiva 190L Single Door Refrigerator' AS PRODUCT_NAME, 'Arctiva' AS BRAND, 'ARC-RF190' AS MODEL_NO, 'Refrigerators' AS CAT_NAME, 'Northwind Appliances Distribution' AS SUP_NAME, 17499.00 AS UNIT_PRICE, 8 AS STOCK_QTY, 5 AS REORDER_LEVEL, 12 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'WashWell 7kg Front Load Washing Machine' AS PRODUCT_NAME, 'WashWell' AS BRAND, 'WW-FL70' AS MODEL_NO, 'Washing Machines' AS CAT_NAME, 'BrightHome Wholesale' AS SUP_NAME, 31999.00 AS UNIT_PRICE, 6 AS STOCK_QTY, 3 AS REORDER_LEVEL, 24 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'WashWell 6.5kg Top Load Washing Machine' AS PRODUCT_NAME, 'WashWell' AS BRAND, 'WW-TL65' AS MODEL_NO, 'Washing Machines' AS CAT_NAME, 'BrightHome Wholesale' AS SUP_NAME, 18999.00 AS UNIT_PRICE, 9 AS STOCK_QTY, 3 AS REORDER_LEVEL, 24 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'CoolBreeze 1.5 Ton Split AC' AS PRODUCT_NAME, 'CoolBreeze' AS BRAND, 'CB-AC15' AS MODEL_NO, 'Air Conditioners' AS CAT_NAME, 'Zenith Domestic Traders' AS SUP_NAME, 36999.00 AS UNIT_PRICE, 5 AS STOCK_QTY, 3 AS REORDER_LEVEL, 36 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'CoolBreeze 1.0 Ton Window AC' AS PRODUCT_NAME, 'CoolBreeze' AS BRAND, 'CB-AC10' AS MODEL_NO, 'Air Conditioners' AS CAT_NAME, 'Zenith Domestic Traders' AS SUP_NAME, 26499.00 AS UNIT_PRICE, 2 AS STOCK_QTY, 3 AS REORDER_LEVEL, 24 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'VistaView 43in 4K Smart TV' AS PRODUCT_NAME, 'VistaView' AS BRAND, 'VV-TV43' AS MODEL_NO, 'Televisions' AS CAT_NAME, 'Orion Electronics Supply' AS SUP_NAME, 29999.00 AS UNIT_PRICE, 10 AS STOCK_QTY, 4 AS REORDER_LEVEL, 12 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'VistaView 55in 4K Smart TV' AS PRODUCT_NAME, 'VistaView' AS BRAND, 'VV-TV55' AS MODEL_NO, 'Televisions' AS CAT_NAME, 'Orion Electronics Supply' AS SUP_NAME, 49999.00 AS UNIT_PRICE, 4 AS STOCK_QTY, 4 AS REORDER_LEVEL, 12 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'VistaView 32in HD TV' AS PRODUCT_NAME, 'VistaView' AS BRAND, 'VV-TV32' AS MODEL_NO, 'Televisions' AS CAT_NAME, 'Orion Electronics Supply' AS SUP_NAME, 12999.00 AS UNIT_PRICE, 15 AS STOCK_QTY, 5 AS REORDER_LEVEL, 12 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'HeatWave 25L Solo Microwave' AS PRODUCT_NAME, 'HeatWave' AS BRAND, 'HW-MW25' AS MODEL_NO, 'Microwave Ovens' AS CAT_NAME, 'Orion Electronics Supply' AS SUP_NAME, 7499.00 AS UNIT_PRICE, 14 AS STOCK_QTY, 5 AS REORDER_LEVEL, 12 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'HeatWave 30L Convection Microwave' AS PRODUCT_NAME, 'HeatWave' AS BRAND, 'HW-MW30' AS MODEL_NO, 'Microwave Ovens' AS CAT_NAME, 'Orion Electronics Supply' AS SUP_NAME, 12499.00 AS UNIT_PRICE, 7 AS STOCK_QTY, 3 AS REORDER_LEVEL, 12 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'KitchenPro Mixer Grinder 750W' AS PRODUCT_NAME, 'KitchenPro' AS BRAND, 'KP-MG75' AS MODEL_NO, 'Small Kitchen Appliances' AS CAT_NAME, 'BrightHome Wholesale' AS SUP_NAME, 3299.00 AS UNIT_PRICE, 25 AS STOCK_QTY, 10 AS REORDER_LEVEL, 24 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'KitchenPro Induction Cooktop 2000W' AS PRODUCT_NAME, 'KitchenPro' AS BRAND, 'KP-IC20' AS MODEL_NO, 'Small Kitchen Appliances' AS CAT_NAME, 'BrightHome Wholesale' AS SUP_NAME, 2899.00 AS UNIT_PRICE, 18 AS STOCK_QTY, 8 AS REORDER_LEVEL, 12 AS WARRANTY_MONTHS FROM DUAL
    UNION ALL SELECT 'Aurora Electric Kettle 1.8L' AS PRODUCT_NAME, 'Aurora' AS BRAND, 'AU-EK18' AS MODEL_NO, 'Small Kitchen Appliances' AS CAT_NAME, 'Northwind Appliances Distribution' AS SUP_NAME, 1199.00 AS UNIT_PRICE, 40 AS STOCK_QTY, 15 AS REORDER_LEVEL, 12 AS WARRANTY_MONTHS FROM DUAL
  ) x
  JOIN CATEGORIES c  ON c.CATEGORY_NAME = x.CAT_NAME
  JOIN SUPPLIERS  sp ON sp.SUPPLIER_NAME = x.SUP_NAME
) s ON (t.MODEL_NO = s.MODEL_NO)
WHEN NOT MATCHED THEN INSERT (PRODUCT_NAME, BRAND, MODEL_NO, CATEGORY_ID, SUPPLIER_ID, UNIT_PRICE, STOCK_QTY, REORDER_LEVEL, WARRANTY_MONTHS)
 VALUES (s.PRODUCT_NAME, s.BRAND, s.MODEL_NO, s.CATEGORY_ID, s.SUPPLIER_ID, s.UNIT_PRICE, s.STOCK_QTY, s.REORDER_LEVEL, s.WARRANTY_MONTHS);

-- 6. SALES (customer / employee resolved by e-mail; TOTAL_AMOUNT = sum of its items)
MERGE INTO SALES t USING (
  SELECT x.INVOICE_NO, c.CUSTOMER_ID, e.EMPLOYEE_ID, x.SALE_DATE, x.PAYMENT_METHOD, x.TOTAL_AMOUNT
  FROM (
    SELECT 'INV-000001' AS INVOICE_NO, 'anita.rao@demo-mail.example.com' AS CUST_EMAIL, 'asha.menon@applstore-demo.example.com' AS EMP_EMAIL, TIMESTAMP '2025-11-03 10:15:00' AS SALE_DATE, 'CARD' AS PAYMENT_METHOD, 35597.00 AS TOTAL_AMOUNT FROM DUAL
    UNION ALL SELECT 'INV-000002' AS INVOICE_NO, 'bharat.kamath@demo-mail.example.com' AS CUST_EMAIL, 'rohan.pereira@applstore-demo.example.com' AS EMP_EMAIL, TIMESTAMP '2025-11-18 14:40:00' AS SALE_DATE, 'UPI' AS PAYMENT_METHOD, 49999.00 AS TOTAL_AMOUNT FROM DUAL
    UNION ALL SELECT 'INV-000003' AS INVOICE_NO, 'chitra.iyer@demo-mail.example.com' AS CUST_EMAIL, 'asha.menon@applstore-demo.example.com' AS EMP_EMAIL, TIMESTAMP '2025-12-05 11:05:00' AS SALE_DATE, 'CASH' AS PAYMENT_METHOD, 10398.00 AS TOTAL_AMOUNT FROM DUAL
    UNION ALL SELECT 'INV-000004' AS INVOICE_NO, 'anita.rao@demo-mail.example.com' AS CUST_EMAIL, 'meera.nair@applstore-demo.example.com' AS EMP_EMAIL, TIMESTAMP '2025-12-22 16:20:00' AS SALE_DATE, 'CARD' AS PAYMENT_METHOD, 66998.00 AS TOTAL_AMOUNT FROM DUAL
    UNION ALL SELECT 'INV-000005' AS INVOICE_NO, 'dev.naik@demo-mail.example.com' AS CUST_EMAIL, 'rohan.pereira@applstore-demo.example.com' AS EMP_EMAIL, TIMESTAMP '2026-01-09 12:00:00' AS SALE_DATE, 'BANK_TRANSFER' AS PAYMENT_METHOD, 49498.00 AS TOTAL_AMOUNT FROM DUAL
    UNION ALL SELECT 'INV-000006' AS INVOICE_NO, 'esha.pinto@demo-mail.example.com' AS CUST_EMAIL, 'asha.menon@applstore-demo.example.com' AS EMP_EMAIL, TIMESTAMP '2026-01-27 17:30:00' AS SALE_DATE, 'UPI' AS PAYMENT_METHOD, 21596.00 AS TOTAL_AMOUNT FROM DUAL
    UNION ALL SELECT 'INV-000007' AS INVOICE_NO, 'bharat.kamath@demo-mail.example.com' AS CUST_EMAIL, 'karan.shetty@applstore-demo.example.com' AS EMP_EMAIL, TIMESTAMP '2026-02-10 10:45:00' AS SALE_DATE, 'CARD' AS PAYMENT_METHOD, 45498.00 AS TOTAL_AMOUNT FROM DUAL
    UNION ALL SELECT 'INV-000008' AS INVOICE_NO, 'farhan.sheikh@demo-mail.example.com' AS CUST_EMAIL, 'meera.nair@applstore-demo.example.com' AS EMP_EMAIL, TIMESTAMP '2026-02-21 13:10:00' AS SALE_DATE, 'CASH' AS PAYMENT_METHOD, 59998.00 AS TOTAL_AMOUNT FROM DUAL
  ) x
  JOIN CUSTOMERS c ON c.EMAIL = x.CUST_EMAIL
  JOIN EMPLOYEES e ON e.EMAIL = x.EMP_EMAIL
) s ON (t.INVOICE_NO = s.INVOICE_NO)
WHEN NOT MATCHED THEN INSERT (INVOICE_NO, CUSTOMER_ID, EMPLOYEE_ID, SALE_DATE, PAYMENT_METHOD, TOTAL_AMOUNT)
 VALUES (s.INVOICE_NO, s.CUSTOMER_ID, s.EMPLOYEE_ID, s.SALE_DATE, s.PAYMENT_METHOD, s.TOTAL_AMOUNT);

-- 7. SALE_ITEMS (sale / product resolved by invoice number / model number)
MERGE INTO SALE_ITEMS t USING (
  SELECT sa.SALE_ID, p.PRODUCT_ID, x.QUANTITY, x.UNIT_PRICE, x.LINE_TOTAL
  FROM (
    SELECT 'INV-000001' AS INVOICE_NO, 'ARC-RF260' AS MODEL_NO, 1 AS QUANTITY, 28999.00 AS UNIT_PRICE, 28999.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000001' AS INVOICE_NO, 'KP-MG75' AS MODEL_NO, 2 AS QUANTITY, 3299.00 AS UNIT_PRICE, 6598.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000002' AS INVOICE_NO, 'VV-TV55' AS MODEL_NO, 1 AS QUANTITY, 49999.00 AS UNIT_PRICE, 49999.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000003' AS INVOICE_NO, 'HW-MW25' AS MODEL_NO, 1 AS QUANTITY, 7499.00 AS UNIT_PRICE, 7499.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000003' AS INVOICE_NO, 'KP-IC20' AS MODEL_NO, 1 AS QUANTITY, 2899.00 AS UNIT_PRICE, 2899.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000004' AS INVOICE_NO, 'CB-AC15' AS MODEL_NO, 1 AS QUANTITY, 36999.00 AS UNIT_PRICE, 36999.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000004' AS INVOICE_NO, 'VV-TV43' AS MODEL_NO, 1 AS QUANTITY, 29999.00 AS UNIT_PRICE, 29999.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000005' AS INVOICE_NO, 'WW-FL70' AS MODEL_NO, 1 AS QUANTITY, 31999.00 AS UNIT_PRICE, 31999.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000005' AS INVOICE_NO, 'ARC-RF190' AS MODEL_NO, 1 AS QUANTITY, 17499.00 AS UNIT_PRICE, 17499.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000006' AS INVOICE_NO, 'KP-MG75' AS MODEL_NO, 1 AS QUANTITY, 3299.00 AS UNIT_PRICE, 3299.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000006' AS INVOICE_NO, 'KP-IC20' AS MODEL_NO, 2 AS QUANTITY, 2899.00 AS UNIT_PRICE, 5798.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000006' AS INVOICE_NO, 'HW-MW30' AS MODEL_NO, 1 AS QUANTITY, 12499.00 AS UNIT_PRICE, 12499.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000007' AS INVOICE_NO, 'CB-AC10' AS MODEL_NO, 1 AS QUANTITY, 26499.00 AS UNIT_PRICE, 26499.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000007' AS INVOICE_NO, 'WW-TL65' AS MODEL_NO, 1 AS QUANTITY, 18999.00 AS UNIT_PRICE, 18999.00 AS LINE_TOTAL FROM DUAL
    UNION ALL SELECT 'INV-000008' AS INVOICE_NO, 'VV-TV43' AS MODEL_NO, 2 AS QUANTITY, 29999.00 AS UNIT_PRICE, 59998.00 AS LINE_TOTAL FROM DUAL
  ) x
  JOIN SALES    sa ON sa.INVOICE_NO = x.INVOICE_NO
  JOIN PRODUCTS p  ON p.MODEL_NO = x.MODEL_NO
) s ON (t.SALE_ID = s.SALE_ID AND t.PRODUCT_ID = s.PRODUCT_ID)
WHEN NOT MATCHED THEN INSERT (SALE_ID, PRODUCT_ID, QUANTITY, UNIT_PRICE, LINE_TOTAL)
 VALUES (s.SALE_ID, s.PRODUCT_ID, s.QUANTITY, s.UNIT_PRICE, s.LINE_TOTAL);

COMMIT;

-- Verification: expected 6 / 4 / 14 / 8 / 4 / 8 / 15 rows on a first run
SELECT 'CATEGORIES' AS TBL, COUNT(*) AS ROW_COUNT FROM CATEGORIES UNION ALL
SELECT 'SUPPLIERS', COUNT(*) FROM SUPPLIERS UNION ALL
SELECT 'PRODUCTS', COUNT(*) FROM PRODUCTS UNION ALL
SELECT 'CUSTOMERS', COUNT(*) FROM CUSTOMERS UNION ALL
SELECT 'EMPLOYEES', COUNT(*) FROM EMPLOYEES UNION ALL
SELECT 'SALES', COUNT(*) FROM SALES UNION ALL
SELECT 'SALE_ITEMS', COUNT(*) FROM SALE_ITEMS;
